var USTAV = [{"name": "Дисциплинарный устав Вооружённых Сил и ФСВНГ", "url": "https://forum.russia.online/threads/%F0%9F%9B%91distsiplinarnyi-ustav-vooruzhennykh-sil-rossiiskoi-federatsii%F0%9F%9B%91.13878/", "abbr": "ДУ", "cats": [{"title": "Общие положения", "arts": [{"title": "Статья 1. Сфера действия и иерархия норм", "html": "<p>Настоящий Устав устанавливает основы воинской дисциплины, порядок применения дисциплинарных мер и меры поощрения военнослужащих Вооружённых Сил и сотрудников ФСВНГ.</p>", "id": "ду-c0-a0", "num": "1"}, {"title": "Статья 2. Воинская дисциплина", "html": "<p>Воинская дисциплина основывается на сознательном исполнении обязанностей, соблюдении субординации, уважении к службе и достоинству других лиц, бережном отношении к имуществу и готовности действовать в интересах подразделения.</p><p>Военнослужащий обязан соблюдать законодательство и уставы, исполнять законные приказы, поддерживать порядок, не допускать действий, подрывающих безопасность службы или авторитет ведомства.</p>", "id": "ду-c0-a1", "num": "2"}, {"title": "Статья 3. Ответственность командования", "html": "<p>Командир организует службу, поддерживает дисциплину, рассматривает сведения о нарушениях в пределах компетенции и принимает меры, соразмерные тяжести проступка.</p><p>Командиру запрещается унижать подчинённых, применять неуставное физическое или психологическое воздействие, скрывать сведения о серьёзном нарушении либо преследовать военнослужащего за добросовестное обращение.</p>", "id": "ду-c0-a2", "num": "3"}, {"title": "Статья 4. Полномочия Военной полиции и ОСБ", "html": "<p>Военная полиция выявляет нарушения, самостоятельно рассматривает / выносит / решает вопросы по привлечению к ответственности военнослужащих, в том числе по вопросам административной, дисциплинарной, уголовной в соответствие с процессуальным законодательством, обеспечивает порядок на военных объектах и передаёт информацию о нарушениях уполномоченным должностным лицам. Военная полиция действует в рамках законодательства и уставов.</p><p>При выявлении нарушения сотрудником ФСВНГ, включая РВО, Кадровую службу и ОМОН, Военная полиция передаёт материалы и сведения в ОСБ. Самостоятельно дисциплинарные взыскания сотрудникам ФСВНГ Военная полиция не назначает.</p><p>При выявлении нарушения сотрудником ВС, ОСБ передаёт материалы и сведения в военную полицию. Самостоятельно дисциплинарные взыскания сотрудникам ВС ОСБ не назначает.</p><p>ОСБ рассматривает полученную информацию, самостоятельно рассматривает / выносит / решает вопросы по привлечению к ответственности ФСВНГ, в том числе по вопросам административной, дисциплинарной, уголовной в соответствие с процессуальным законодательством, и действует в пределах своей компетенции. Решение о дисциплинарной ответственности принимается уполномоченным должностным лицом после проверки обстоятельств.</p><p>ОСБ работает по нарушениям только внутри подразделений ФСВНГ.</p>", "id": "ду-c0-a3", "num": "4"}], "id": "ду-c0"}, {"title": "Взыскания и порядок их применения", "arts": [{"title": "Статья 5. Принципы дисциплинарной ответственности", "html": "<p>Взыскание применяется за виновное нарушение и должно быть справедливым, соразмерным его характеру, последствиям, роли лица и обстоятельствам совершения.</p><p>При назначении взыскания учитываются признание вины, содействие проверке, повторность, степень опасности нарушения и прежнее отношение военнослужащего к службе.</p><p>За один проступок не может назначаться более одного дисциплинарного взыскания. Дисциплинарное взыскание не заменяет ответственность, установленную законодательством.</p><p>При выборе меры учитываются тяжесть нарушения, последствия, степень вины, повторность и поведение военнослужащего. Взыскание должно быть адекватным и соразмерным проступку. Если статья предусматривает несколько возможных мер, уполномоченное лицо выбирает одну из них с учётом обстоятельств нарушения.</p>", "id": "ду-c1-a0", "num": "5"}, {"title": "Статья 6. Виды дисциплинарных взысканий", "html": "<p>К военнослужащему или сотруднику, признанному виновным в дисциплинарном проступке, в пределах компетенции могут применяться следующие меры:</p><ul><li>беседа (устное предупреждение) — применяется за малозначительное нарушение и не вносится в планшет;</li><li>устный выговор — применяется за нарушение средней тяжести и учитывается в планшете как один активный выговор;</li><li>переаттестация — проводится для повторной проверки знаний и соответствия военнослужащего занимаемой должности;</li><li>строгий выговор — применяется за грубое, повторное либо создавшее угрозу нарушение и учитывается в планшете как два активных выговора;</li><li>понижение в должности или звании — только уполномоченным руководителем в порядке, установленном внутренними актами;</li><li>увольнение со службы — применяется за наиболее тяжкие нарушения, грубую повторность либо накопление активных выговоров; оформляется уполномоченным руководителем после рассмотрения материалов проверки.</li></ul>", "id": "ду-c1-a1", "num": "6"}, {"title": "Статья 6.1. Учёт и отработка активных выговоров", "html": "<p>Устный выговор учитывается в планшете как один активный выговор. Строгий выговор учитывается в планшете как два активных выговора. Беседа в планшет не вносится.</p><p>Военнослужащий обязан отработать активный выговор в течение 48 часов с момента его выдачи в порядке, установленном командованием или руководителем подразделения.</p><p>Если активный выговор не отработан в течение 48 часов, военнослужащему выдаётся дополнительный устный выговор. Если выговор не отработан в течение 96 часов с момента первоначальной выдачи, выдаётся ещё один устный выговор.</p><p>Накопление трёх активных выговоров в планшете влечёт увольнение со службы. Решение об увольнении оформляется уполномоченным руководителем после проверки актуальности выговоров и обстоятельств их выдачи. Отработанный, снятый либо признанный необоснованным выговор не учитывается при подсчёте активных выговоров.</p><p>Если медицинское освобождение объективно препятствует установленной форме отработки выговора, военнослужащему предоставляется возможность отработки способом, совместимым с медицинскими ограничениями.</p><p>При отсутствии доступного совместимого способа течение сроков отработки, включая сроки 48 и 96 часов, приостанавливается на период подтверждённой невозможности отработки. После окончания указанного периода течение оставшегося срока возобновляется.</p><p>Приостановление и возобновление срока фиксируются уполномоченным должностным лицом. За период приостановления дополнительные взыскания за просрочку не применяются.</p>", "id": "ду-c1-a2", "num": "6.1"}, {"title": "Статья 6.2. Ограничение на повышение при наличии дисциплинарного взыскания", "html": "<p>Военнослужащий, имеющий действующее дисциплинарное взыскание, не может быть представлен к повышению в воинском звании или назначен на должность, предусматривающую повышение в воинском звании, до момента снятия либо прекращения действия дисциплинарного взыскания.</p><p>Наличие дисциплинарного взыскания учитывается на момент рассмотрения вопроса о повышении. При наличии действующего взыскания решение о повышении не может быть принято до его снятия или прекращения в установленном настоящим Уставом порядке.</p><p>После снятия либо прекращения действия дисциплинарного взыскания военнослужащий может быть представлен к повышению на общих основаниях при соблюдении остальных требований, установленных настоящим Уставом и иными нормативными актами.</p><p class=\"note\">Примечание: Подача жалобы на дисциплинарное взыскание не прекращает его действия и не является основанием для повышения до момента рассмотрения жалобы и принятия окончательного решения.</p>", "id": "ду-c1-a3", "num": "6.2"}, {"title": "Статья 7. Порядок рассмотрения нарушения", "html": "<p>До применения взыскания уполномоченное лицо устанавливает обстоятельства нарушения, проверяет доступные доказательства и, когда это возможно, получает объяснение лица, в отношении которого ведётся проверка.</p><p>Решение о применении взыскания должно содержать существо нарушения, конкретную нарушенную норму, установленные обстоятельства, вид взыскания и должностное лицо, его применившее.</p><p>Лицо, в отношении которого применено взыскание, вправе обжаловать решение в установленном настоящим Уставом порядке.</p><p>Неустранимые сомнения в обстоятельствах проступка толкуются в пользу военнослужащего или сотрудника.</p>", "id": "ду-c1-a4", "num": "7"}, {"title": "Статья 7.1. Основания дисциплинарной ответственности (обжалование)", "html": "<p>Рассмотрение обжалования наказаний на дисциплинарные взыскания осуществляется исключительно ОСБ и ВП. Командир или иное должностное лицо, применившее дисциплинарное взыскание, не вправе самостоятельно рассматривать жалобу на собственное решение. ОСБ и ВП при рассмотрении жалобы вправе проверить:</p><ul><li>наличие факта нарушения;</li><li>соответствие действий лица конкретной норме Устава;</li><li>наличие и достаточность имеющихся доказательств;</li><li>соблюдение порядка применения взыскания;</li><li>соответствие применённого взыскания установленным обстоятельствам.</li></ul><p>По результатам рассмотрения жалобы ОСБ или ВП вправе оставить взыскание в силе, изменить его либо отменить при установлении необоснованности или нарушения порядка его применения. Подача жалобы не является дисциплинарным проступком и не может сама по себе являться основанием для применения нового взыскания. Запрещается препятствовать подаче жалобы, требовать её отзыва либо оказывать давление на лицо в связи с обращением в ОСБ или ВП.</p><p class=\"note\">Примечание: Снятие, отмена либо изменение дисциплинарного взыскания без достаточных оснований, в том числе по личной договорённости, знакомству или иной личной заинтересованности («по блату»), запрещается.</p><p>Должностное лицо ОСБ или ВП, необоснованно снявшее либо изменившее дисциплинарное взыскание, подлежит дисциплинарной ответственности в соответствии с настоящим Уставом.</p>", "id": "ду-c1-a5", "num": "7.1"}], "id": "ду-c1"}, {"title": "Проступки: субординация и несение службы", "arts": [{"title": "Статья 8. Нарушение субординации", "html": "<p>Неисполнение законного приказа, умышленный отказ от исполнения законного распоряжения, действия, препятствующие исполнению законного приказа, а также нарушение установленного порядка обращения между военнослужащими являются нарушением субординации.</p><p>Не является нарушением субординации обращение за разъяснением приказа, доклад о невозможности его исполнения, сообщение о незаконности приказа, подача рапорта или жалобы в установленном порядке.</p><p>Оскорбление, угроза, применение насилия либо иное грубое воздействие в отношении командира, старшего по должности или другого военнослужащего рассматриваются как грубое нарушение субординации.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение при угрозе, насилии либо грубой повторности.</p>", "id": "ду-c2-a0", "num": "8"}, {"title": "Статья 9. Самовольное оставление места службы", "html": "<p>Самовольное оставление части, подразделения, места несения службы или самовольное прекращение исполнения служебной задачи без уважительной причины является дисциплинарным проступком.</p><p>Тяжесть проступка определяется с учётом продолжительности отсутствия, последствий и статуса военнослужащего. Обстоятельства, объективно исключавшие возможность прибыть или продолжить службу, подлежат учёту.</p><p>Подтверждённая невозможность продолжения службы по состоянию здоровья, экстренное обращение за медицинской помощью или эвакуация подлежат обязательному учёту при рассмотрении обстоятельств отсутствия.</p><p>Невозможность своевременно доложить о состоянии здоровья сама по себе не образует нарушение, если она была объективно обусловлена состоянием военнослужащего. При первой возможности военнослужащий либо медицинский работник уведомляет командование.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение при оставлении поста, существенных последствиях либо повторном нарушении.</p>", "id": "ду-c2-a1", "num": "9"}, {"title": "Статья 10. Уклонение от службы и обязательных мероприятий", "html": "<p>Неявка без уважительной причины на обязательное построение, занятие, медицинский осмотр, инструктаж, служебное мероприятие или иной обязательный формат службы является дисциплинарным проступком.</p><p>Уклонением от службы также является намеренное прекращение уже принятого военнослужащим наряда, патруля либо иной служебной задачи без передачи её в установленном порядке.</p><p>Действующее медицинское освобождение является уважительной причиной неисполнения тех обязанностей и неявки на те мероприятия, на которые распространяются установленные ограничения.</p><p>Ответственность за неявку на медицинский осмотр применяется при условии, что осмотр назначен уполномоченным лицом, требование доведено до военнослужащего и у него имелась возможность явиться.</p><p>Несение постовой службы до прибытия смены, получение экстренной помощи и иные подтверждённые обстоятельства, объективно препятствующие явке, учитываются при установлении вины.</p><p class=\"measures\">Возможные меры: беседа, устный выговор, строгий выговор; при грубой повторности или срыве служебной задачи — увольнение.</p>", "id": "ду-c2-a2", "num": "10"}, {"title": "Статья 11. Нарушение порядка несения службы", "html": "<p>Ненадлежащее несение караульной, патрульной, внутренней или иной служебной обязанности, если оно создало или могло создать угрозу безопасности, порядку или имуществу, является дисциплинарным проступком.</p><p>К ненадлежащему несению службы относятся, в частности:</p><ul><li>сон во время исполнения служебной обязанности;</li><li>оставление поста, маршрута или места несения службы без установленного разрешения;</li><li>необоснованное прекращение патрулирования либо иной служебной задачи;</li><li>игнорирование обязательной служебной связи;</li><li>несвоевременная передача службы;</li><li>отсутствие необходимого наблюдения за охраняемой территорией, объектом либо лицами;</li><li>совершение действий, не связанных с исполнением службы, если они препятствуют выполнению служебной обязанности;</li><li>иное бездействие или действие, нарушающее установленный порядок несения службы.</li></ul><p>Самостоятельное заступление на пост или патруль допускается в рамках действующих уставов. Отсутствие индивидуального назначения либо журнала поста не освобождает лицо от ответственности за нарушение фактически принятой им службы.</p><p class=\"measures\">Возможные меры: беседа, устный выговор или строгий выговор; при создании угрозы безопасности, существенном вреде либо грубой повторности — увольнение.</p>", "id": "ду-c2-a3", "num": "11"}, {"title": "Статья 21. Поведение в строю и на территории части", "html": "<p>Военнослужащий обязан соблюдать установленный порядок на построениях, плацу, в казармах и на территории части, не мешать проведению служебных мероприятий и не создавать опасность другим лицам.</p><p>Нарушением порядка на построении является умышленное действие или бездействие, препятствующее проведению построения, выполнению команд, размещению личного состава либо обеспечению безопасности.</p><p>Самовольное передвижение бегом по плацу во время проведения построения при наличии сформированного строя запрещается. Исключение составляют случаи исполнения команды или распоряжения командования, необходимости оказания помощи либо обеспечения безопасности.</p><p>Случайное перемещение, выполнение служебного распоряжения либо иное действие, объективно необходимое для выполнения службы, не является нарушением настоящей статьи.</p><p class=\"measures\">Возможные меры: беседа, устный выговор или строгий выговор при повторном нарушении, срыве мероприятия либо создании опасности.</p>", "id": "ду-c2-a4", "num": "21"}, {"title": "Статья 27. Халатность", "html": "<p>Неисполнение либо ненадлежащее исполнение обязанностей вследствие недобросовестного отношения к службе, если это повлекло или могло повлечь вред безопасности, порядку, имуществу или интересам службы, является дисциплинарным проступком.</p><p>Ошибка, допущенная при добросовестном исполнении обязанности, сама по себе не является халатностью.</p><p>Для установления халатности необходимо установить конкретную обязанность лица, способ её нарушения, фактическую возможность надлежащего исполнения, вину и причинную связь между нарушением и наступившими либо возможными последствиями.</p><p>При оценке исполнения медицинских обязанностей учитываются подготовка работника, предоставленные полномочия, доступность необходимых средств и фактическая возможность оказать помощь.</p><p>Неблагоприятный результат оказания помощи сам по себе не доказывает халатность.</p><p>Неисполнение командиром доведённых до него действующих медицинских ограничений при наличии возможности обеспечить их соблюдение оценивается по настоящей статье либо иной применимой специальной норме с учётом характера вины и последствий.</p><p class=\"measures\">Возможные меры: беседа, устный выговор, строгий выговор или увольнение в зависимости от возможного либо наступившего вреда.</p>", "id": "ду-c2-a5", "num": "27"}], "id": "ду-c2"}, {"title": "Проступки: порядок, безопасность, имущество и оружие", "arts": [{"title": "Статья 12. Нарушение порядка и общественной безопасности", "html": "<p>Действия или бездействие военнослужащего, нарушающие общественный порядок, безопасность военного объекта, установленный режим либо создающие угрозу гражданам, военнослужащим или имуществу, являются дисциплинарным проступком.</p><p class=\"measures\">Возможные меры: беседа, устный выговор или строгий выговор; при серьёзной угрозе безопасности, значимых последствиях либо грубой повторности — увольнение.</p>", "id": "ду-c3-a0", "num": "12"}, {"title": "Статья 12.1. Нарушение требований пожарной безопасности", "html": "<p>Нарушение требований пожарной безопасности, неосторожное обращение с огнём, создание пожароопасной ситуации, использование источников огня в запрещённой зоне либо игнорирование требований безопасности на складе, в казарме, гараже, технике или ином объекте Армии является дисциплинарным проступком.</p><p>За нарушение может применяться беседа, устный выговор или строгий выговор. Если нарушение создало реальную угрозу жизни, повлекло ущерб имуществу либо совершено повторно, применяется строгий выговор или увольнение.</p><p>Курение, использование электронных устройств для курения, кальянов и иных аналогичных средств в помещениях, на посту, на складе, вблизи техники, вооружения, горюче-смазочных материалов либо в иной запрещённой зоне является нарушением требований пожарной безопасности.</p><p class=\"measures\">Возможные меры: беседа, устный выговор или строгий выговор; при реальной угрозе жизни, ущербе имуществу либо повторном нарушении — строгий выговор или увольнение.</p>", "id": "ду-c3-a1", "num": "12.1"}, {"title": "Статья 13. Повреждение, утрата и незаконное использование имущества", "html": "<p>Умышленные либо небрежные действия, повлекшие утрату, порчу, повреждение или неправомерное использование государственного, ведомственного либо чужого имущества, являются дисциплинарным проступком.</p><p>Сам факт отсутствия имущества не является достаточным основанием для признания военнослужащего виновным в его утрате.</p><p>При наличии нескольких лиц, ответственных за имущество, ответственность каждого определяется индивидуально с учётом его фактических обязанностей и действий.</p><p>Нарушение, содержащее признаки преступления или административного правонарушения, передаётся для рассмотрения в порядке, установленном законодательством.</p><p>Хищение, присвоение, незаконное удержание либо передача государственного, ведомственного или чужого имущества без законных оснований является грубым дисциплинарным проступком.</p><p>Положения настоящей статьи распространяются на медицинские препараты, медицинское имущество и расходные материалы.</p><p>Использование медицинских препаратов, медицинского имущества допускается исключительно медицинскими работниками в пределах их профессиональной компетенции и в соответствии с установленными правилами. Исключение: дефибриллятор, аптечки, бинты.</p><p>Использование указанных средств иными лицами рассматривается как неправомерное использование имущества и влечёт ответственность в соответствии с настоящей статьёй.</p><p>Нарушение порядка учёта без установленных фактов утраты, присвоения, незаконной передачи или использования имущества не признаётся автоматически хищением либо утратой и оценивается по фактическим обстоятельствам.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от характера вины, стоимости имущества и наступивших последствий.</p>", "id": "ду-c3-a2", "num": "13"}, {"title": "Статья 14. Оружие, боеприпасы и специальные средства", "html": "<p>Нарушение правил хранения, учёта, переноски, передачи или применения оружия, боеприпасов и специальных средств является дисциплинарным проступком.</p><p>Утеря, порча, оставление без присмотра либо небрежное хранение указанных предметов рассматриваются с учётом создаваемой опасности и наступивших последствий.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от опасности нарушения, последствий и повторности.</p>", "id": "ду-c3-a3", "num": "14"}, {"title": "Статья 15. Состояние опьянения и запрещённые вещества", "html": "<p>Появление на службе в состоянии алкогольного, наркотического или иного опьянения, употребление запрещённых веществ во время службы, а равно необоснованный отказ от освидетельствования в случаях, предусмотренных законодательством, являются дисциплинарными проступками.</p><p class=\"measures\">Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.</p>", "id": "ду-c3-a4", "num": "15"}, {"title": "Статья 17. Военная форма и внешний вид", "html": "<p>Нарушение правил ношения военной формы, знаков различия, средств индивидуальной защиты и иных обязательных элементов внешнего вида является дисциплинарным проступком, если оно не обусловлено служебной необходимостью.</p><p>Требования к форме, причёске, растительности на лице, средствам индивидуальной защиты и гигиене устанавливаются общим уставом и обязательны в пределах, прямо предусмотренных таким уставом.</p><p>Вынужденное изменение формы или внешнего вида, вызванное выполнением служебной задачи, чрезвычайной ситуацией, необходимостью обеспечения безопасности либо иными объективными обстоятельствами, не является нарушением.</p><p>Требования к внешнему виду должны быть доведены до военнослужащих до начала их применения.</p><p class=\"measures\">Возможные меры: беседа, устный выговор или строгий выговор при повторном либо демонстративном нарушении.</p>", "id": "ду-c3-a5", "num": "17"}, {"title": "Статья 22. Символика, ритуалы и азартные игры", "html": "<p>Надругательство над государственными или ведомственными символами, срыв установленного воинского ритуала, а также организация или участие в азартных играх в служебное время либо на служебной территории являются дисциплинарными проступками.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение при грубом, публичном либо повторном нарушении.</p>", "id": "ду-c3-a6", "num": "22"}, {"title": "Статья 29. Режим объекта, связь и транспорт", "html": "<p>Ведение отдельного журнала поста или назначение военнослужащего на пост не являются признанием нарушения. Значимые инциденты фиксируются служебным сообщением, рапортом либо иным установленным способом.</p><p>Использование личного транспорта на территории воинской части допускается только по маршрутам и через пункты пропуска, прямо определённые действующим караульным уставом или распоряжением командования.</p><p>Личный транспорт, въезжающий на территорию части, должен быть зарегистрирован в реестре личных Т/С.</p><p>Служебный транспорт используется исключительно для выполнения служебных задач. Запрещается использовать служебный автомобиль для личных поездок, развлечений или иных целей, не связанных с исполнением служебных обязанностей.</p><p>Запрещается использовать служебный автомобиль для перевозки личных вещей, имущества или иных лиц, если такая перевозка не связана с выполнением служебной задачи либо не разрешена уполномоченным должностным лицом.</p><p>Запрещается передавать служебный автомобиль другому лицу без служебной необходимости и разрешения уполномоченного должностного лица.</p><p>Использование служебного транспорта для личных целей допускается только в случае, если такое использование непосредственно связано с выполнением служебной задачи либо отдельно разрешено уполномоченным должностным лицом.</p><p>При возникновении необходимости использования служебного транспорта вне установленного назначения военнослужащий обязан получить соответствующее разрешение до начала поездки, за исключением чрезвычайной ситуации, когда получение разрешения объективно невозможно.</p><p class=\"measures\">Возможные меры: беседа, устный выговор или строгий выговор; при создании угрозы безопасности, существенных последствиях либо грубой повторности — увольнение.</p>", "id": "ду-c3-a7", "num": "29"}], "id": "ду-c3"}, {"title": "Проступки: информация, власть и этика", "arts": [{"title": "Статья 16. Бездействие командира и незаконное привлечение к ответственности", "html": "<p>Умышленное бездействие командира при наличии сведений о существенном нарушении, сокрытие такого нарушения или воспрепятствование его проверке является дисциплинарным проступком.</p><p>Привлечение военнослужащего к ответственности без установленных оснований, вне предоставленной компетенции либо с нарушением установленного порядка также является дисциплинарным проступком.</p><p>Ответственность за бездействие наступает при одновременном наличии:</p><ul><li>фактической информации о нарушении;</li><li>обязанности принять соответствующие меры;</li><li>реальной возможности принять такие меры;</li><li>умышленного либо недобросовестного бездействия.</li></ul><p>Отсутствие информации о нарушении, объективная невозможность получить такую информацию либо отсутствие фактической возможности принять необходимые меры сами по себе не образуют нарушение.</p><p class=\"measures\">Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.</p>", "id": "ду-c4-a0", "num": "16"}, {"title": "Статья 18. Честь ведомства и дискредитация", "html": "<p>Публичные умышленные действия, высказывания или распространение материалов, содержащих заведомо ложные сведения о Вооружённых Силах, ФСВНГ, их деятельности или символике, совершённые с целью причинения вреда авторитету ведомства, являются дисциплинарным проступком.</p><p>Критика деятельности ведомства, выражение мнения, обращение с жалобой, рапортом или сообщением о нарушении не образуют дисциплинарного проступка сами по себе.</p><p>Добросовестное сообщение о возможном нарушении не признаётся дискредитацией независимо от того, подтвердились ли указанные в сообщении обстоятельства.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение при грубом, публичном либо повторном нарушении.</p>", "id": "ду-c4-a1", "num": "18"}, {"title": "Статья 19. Служебная информация и документы", "html": "<p>Разглашение охраняемой служебной информации, несанкционированный доступ к ней, подделка, уничтожение или неправомерное использование служебных документов являются дисциплинарными проступками.</p><p>Предоставление заведомо ложных сведений в рапорте, объяснении, отчёте или ином служебном документе рассматривается как самостоятельный проступок.</p><p>К служебным документам относятся приказы и приказания, директивы, рапорты и доклады, акты и протоколы, справки и удостоверения, медицинские карточки, заключения, направления и документы учёта медицинских препаратов и имущества.</p><p>Подделка таких документов, оформление фиктивного осмотра или освобождения, внесение заведомо ложных сведений, несанкционированное изменение записей либо разглашение охраняемых медицинских сведений рассматриваются по настоящей статье.</p><p>Добросовестная техническая ошибка, исправленная в установленном порядке, сама по себе не признаётся подделкой или предоставлением заведомо ложных сведений.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от характера информации, последствий и повторности.</p>", "id": "ду-c4-a2", "num": "19"}, {"title": "Статья 20. Злоупотребление полномочиями и конфликт интересов", "html": "<p>Использование служебных полномочий, имущества, доступа, транспорта либо специального статуса в личных интересах, а также принятие решения при неурегулированном конфликте интересов являются дисциплинарными проступками.</p><p>Служебные полномочия не могут использоваться для личной выгоды, давления на граждан или военнослужащих либо обхода установленной процедуры.</p><p>Использование служебного транспорта, имущества или оборудования в личных целях запрещается, если такое использование не связано непосредственно с выполнением служебной задачи либо не разрешено уполномоченным должностным лицом.</p><p>Использование медицинского осмотра, заключения, освобождения или направления на обследование для личной выгоды, давления, мести либо вмешательства в кадровые решения вне предоставленных полномочий является злоупотреблением.</p><p>При возникновении обстоятельств, способных повлиять на объективность принимаемого решения, военнослужащий обязан сообщить об этом непосредственному командиру либо иному уполномоченному лицу.</p><p>Медицинское освобождение не допускается использовать в качестве дисциплинарного наказания.</p><p class=\"measures\">Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.</p>", "id": "ду-c4-a3", "num": "20"}, {"title": "Статья 23. Самоуправство и неуставные взаимоотношения", "html": "<p>Принуждение военнослужащего к действиям, не предусмотренным законодательством, уставом или законным приказом, самовольное применение взысканий, а равно унижение, травля или неуставное воздействие на подчинённого являются дисциплинарными проступками.</p><p>К неуставным взаимоотношениям также относятся: использование подчинённого для выполнения личных поручений; требование передать имущество или денежные средства; угрозы, запугивание или систематическое давление; публичное унижение военнослужащего; принуждение к действиям, не связанным со службой; применение физического воздействия вне предусмотренных случаев; самовольное установление дополнительных обязанностей или ограничений; использование служебного положения для разрешения личного конфликта.</p><p class=\"measures\">Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.</p>", "id": "ду-c4-a4", "num": "23"}, {"title": "Статья 24. Оказание помощи", "html": "<p>Неоказание посильной помощи раненому, пострадавшему, военнослужащему, гражданину либо сотруднику, находящемуся в опасном состоянии, когда помощь могла быть оказана без неоправданного риска, является дисциплинарным проступком.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от опасности ситуации и последствий неоказания помощи.</p>", "id": "ду-c4-a5", "num": "24"}, {"title": "Статья 25. Заведомо ложное сообщение и клевета", "html": "<p>Заведомо ложное сообщение о нарушении, преступлении или происшествии, а равно распространение заведомо недостоверных сведений, порочащих честь и достоинство другого лица, является дисциплинарным проступком.</p><p>Сообщение не признаётся заведомо ложным только на основании того, что указанные в нём сведения впоследствии не подтвердились.</p><p>Для признания сообщения заведомо ложным необходимо установить, что лицо на момент сообщения знало о недостоверности сообщаемых сведений либо сознательно сообщило их вопреки известным ему обстоятельствам.</p><p>Добросовестная жалоба, рапорт, доклад или сообщение о предполагаемом нарушении не является заведомо ложным сообщением, если лицо не знало о недостоверности указанных сведений.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение при тяжких последствиях, грубой клевете либо повторном нарушении.</p>", "id": "ду-c4-a6", "num": "25"}, {"title": "Статья 26. Воспрепятствование законной деятельности", "html": "<p>Неповиновение законным требованиям уполномоченного сотрудника, создание препятствий проверке, служебному мероприятию либо законной деятельности государственного органа является дисциплинарным проступком.</p><p class=\"measures\">Возможные меры: устный выговор, строгий выговор или увольнение при умышленном срыве законной деятельности, угрозе либо грубой повторности.</p>", "id": "ду-c4-a7", "num": "26"}, {"title": "Статья 28. Связи с преступной деятельностью", "html": "<p>Сокрытие достоверно известных сведений о подготовке либо совершении преступления, а также использование служебного положения в интересах преступной деятельности является дисциплинарным проступком и подлежит передаче для рассмотрения по законодательству.</p><p class=\"measures\">Возможные меры: строгий выговор или увольнение. Материалы подлежат передаче для рассмотрения по законодательству.</p>", "id": "ду-c4-a8", "num": "28"}, {"title": "Статья 30. Иные нарушения", "html": "<p>Нарушение обязанностей, прямо установленных законодательством, настоящим Уставом, иными уставами или законным приказом, может являться дисциплинарным проступком при наличии вины и доказанных обстоятельств.</p><p>Общая формулировка настоящей статьи не применяется для обхода специальных норм Устава или назначения взыскания за поведение, которое не было заранее запрещено либо не нарушило конкретную законную обязанность.</p><p>При наличии специальной нормы настоящего Устава применяется специальная норма, а статья 30 не используется вместо неё.</p><p>Лицо не может быть привлечено к дисциплинарной ответственности исключительно на основании настоящей статьи, если невозможно указать конкретную… (в присланном тексте статья обрывается на этом месте)</p>", "id": "ду-c4-a9", "num": "30"}], "id": "ду-c4"}, {"title": "Поощрения", "arts": [{"title": "Статья 31. Основания для поощрения", "html": "<p>Поощрение применяется за добросовестную службу, инициативу, образцовое исполнение обязанностей, успешное выполнение сложной задачи, помощь подразделению, дисциплинированность и иные заслуги перед ведомством.</p>", "id": "ду-c5-a0", "num": "31"}, {"title": "Статья 32. Виды поощрений", "html": "<p>В пределах компетенции могут применяться следующие меры поощрения:</p><ul><li>снятие ранее наложенного дисциплинарного взыскания;</li><li>объявление благодарности;</li><li>награждение ценным подарком либо денежной премией в порядке, установленном проектом;</li><li>досрочное присвоение очередного звания или представление к повышению;</li><li>занесение в книгу почёта либо иную форму публичного признания заслуг.</li></ul>", "id": "ду-c5-a1", "num": "32"}, {"title": "Статья 33. Порядок применения поощрений", "html": "<p>Поощрение объявляется уполномоченным должностным лицом и должно быть обосновано конкретными заслугами военнослужащего или сотрудника. Поощрение не освобождает от ответственности за совершённые нарушения.</p>", "id": "ду-c5-a2", "num": "33"}], "id": "ду-c5"}, {"title": "Заключительные положения", "arts": [{"title": "Статья 34. Применение Устава", "html": "<p>Настоящий Устав применяется совместно с общим уставом Вооружённых Сил, уставом караульно-постовой службы и действующим законодательством проекта.</p><p>Положения Устава подлежат периодическому пересмотру командованием при изменении законодательства, структуры ведомств или игровых механик. Изменения не могут ухудшать положение лица задним числом.</p>", "id": "ду-c6-a0", "num": "34"}, {"title": "Статья 35. Толкование", "html": "<p>Официальное толкование положений настоящего Устава осуществляется уполномоченным руководством проекта в соответствии с законодательством. При наличии пробела применяется наиболее близкая по смыслу норма с соблюдением принципов справедливости, соразмерности и презумпции добросовестности.</p>", "id": "ду-c6-a1", "num": "35"}], "id": "ду-c6"}, {"title": "Медицинские проверки и ответственность", "arts": [{"title": "Статья 36. Обязательность медицинских проверок", "html": "<p>Военнослужащие обязаны своевременно проходить проверки, назначенные Медицинской ротой, в установленное руководством время.</p><p>Неявка либо пропуск обязательной проверки без уважительной причины является дисциплинарным нарушением.</p>", "id": "ду-c7-a0", "num": "36"}, {"title": "Статья 37. Рекомендации Медицинской роты", "html": "<p>По результатам проверки сотрудники Медицинской роты вправе выдавать военнослужащему рекомендации, связанные с дальнейшим прохождением службы и устранением выявленных нарушений.</p><p>Военнослужащий обязан ознакомиться с выданными ему рекомендациями и выполнить обязательные требования в установленный срок.</p>", "id": "ду-c7-a1", "num": "37"}, {"title": "Статья 38. Игнорирование рекомендаций", "html": "<p>Систематическое либо намеренное игнорирование рекомендаций Медицинской роты рассматривается как нарушение служебной дисциплины.</p><p>При повторном игнорировании рекомендаций или отказе от выполнения обязательных требований к военнослужащему может быть применено дисциплинарное взыскание.</p>", "id": "ду-c7-a2", "num": "38"}, {"title": "Статья 39. Ответственность за пропуск проверки", "html": "<p>За пропуск обязательной проверки Медицинской роты без уважительной причины к военнослужащему применяется дисциплинарное взыскание в соответствии с настоящим Уставом.</p>", "id": "ду-c7-a3", "num": "39"}, {"title": "Статья 40. Уважительные причины", "html": "<p>Уважительными причинами пропуска проверки могут являться служебная необходимость, отсутствие военнослужащего по согласованной причине либо иные обстоятельства, признанные руководством уважительными.</p><p class=\"note\">Примечание: о невозможности пройти проверку военнослужащий обязан заранее уведомить сотрудника Медицинской роты либо непосредственное руководство.</p>", "id": "ду-c7-a4", "num": "40"}], "id": "ду-c7"}]}, {"name": "Устав Вооружённых Сил и ФСВНГ", "url": "https://forum.russia.online/threads/%F0%9F%9B%91ustav-vooruzhennykh-sil-i-federal-naya-sluzhba-voisk-natsional-noi-gvardii%F0%9F%9B%91.13872/", "abbr": "ВУ", "cats": [{"title": "Глава I. Общие положения", "arts": [{"title": "Преамбула", "html": "<p>Настоящий Устав определяет права и обязанности военнослужащих Вооружённых Сил и Федеральной службы войск национальной гвардии, порядок взаимодействия, обязанности должностных лиц и правила внутреннего порядка. Все военнослужащие независимо от звания и должности обязаны руководствоваться настоящим Уставом.</p>", "id": "ву-c0-a0", "num": ""}, {"title": "Статья 1.1. Соблюдение Устава", "html": "<p>Каждый военнослужащий обязан знать и соблюдать положения настоящего Устава. Незнание Устава не освобождает от ответственности.</p>", "id": "ву-c0-a1", "num": "1.1"}, {"title": "Статья 1.2. Воинский долг", "html": "<p>Каждый военнослужащий обязан честно и качественно исполнять воинский долг, защищать национальные интересы, суверенитет и целостность территории Российской Федерации.</p>", "id": "ву-c0-a2", "num": "1.2"}, {"title": "Статья 1.3. Исполнение приказов", "html": "<p>Военнослужащий обязан исполнить законный приказ начальника. При получении заведомо незаконного приказа военнослужащий не исполняет его и незамедлительно докладывает непосредственному либо вышестоящему начальнику.</p>", "id": "ву-c0-a3", "num": "1.3"}, {"title": "Статья 1.4. Репутация Армии", "html": "<p>Запрещены действия, способные нанести ущерб репутации Армии или подорвать доверие к ней.</p>", "id": "ву-c0-a4", "num": "1.4"}, {"title": "Статья 1.5. Обращение по служебным вопросам", "html": "<p>При возникновении служебных вопросов военнослужащий обращается к командиру своего подразделения.</p>", "id": "ву-c0-a5", "num": "1.5"}, {"title": "Статья 1.6. Единоначалие", "html": "<p>Командир наделён распорядительной властью и несёт персональную ответственность за подразделение.</p>", "id": "ву-c0-a6", "num": "1.6"}, {"title": "Статья 1.7. Построения", "html": "<p>Во время объявленного построения военнослужащие обязаны явиться в назначенное место точно и в срок, кроме лиц, несущих службу на посту.</p><p>Военнослужащий, имеющий действующее медицинское освобождение от участия в построениях либо ограничения, несовместимые с условиями их проведения, освобождается от участия на срок действия медицинского заключения. О наличии освобождения военнослужащий сообщает непосредственному командиру, а при невозможности сообщить самостоятельно — через военнослужащего медроты.</p>", "id": "ву-c0-a7", "num": "1.7"}, {"title": "Статья 1.8. Набор", "html": "<p>Набор в ряды Армии осуществляется посредством агитационных мероприятий и призывов по утверждённому графику.</p>", "id": "ву-c0-a8", "num": "1.8"}, {"title": "Статья 1.9. КМБ и Военная академия", "html": "<p>Курс молодого бойца (КМБ) и Укороченный курс молодого бойца (УКМБ) проходятся не более чем за 5 дней, Рота молодого пополнения (РМП) и Академия ФСВНГ (АФСВНГ) — не более чем за 10 дней. После провала Военной академии военнослужащий заносится в чёрный список на срок от 14 до 90 дней по решению командования.</p>", "id": "ву-c0-a9", "num": "1.9"}, {"title": "Статья 1.10. Основания для увольнения", "html": "<p>Основаниями для увольнения являются: собственное желание; грубое нарушение Устава; нарушение законодательства; решение суда или предписание Прокуратуры; непрохождение КМБ, УКМБ, РМП или АФСВНГ; отсутствие в подразделении более 48 часов; нахождение в части без формы; самовольное оставление части; иные прямо предусмотренные настоящим Уставом основания. Наличие дисциплинарных взысканий влечёт последствия в порядке, установленном Дисциплинарным уставом.</p><p>Отсутствие на службе, обусловленное подтверждённым лечением, госпитализацией или медицинским освобождением, не признаётся самовольным отсутствием при условии уведомления командования. Если своевременное уведомление было невозможно по состоянию здоровья, оно осуществляется при первой возможности.</p><p>Само по себе временное медицинское освобождение не является основанием для увольнения. Кадровые решения по состоянию здоровья принимаются уполномоченным должностным лицом на основании надлежащего медицинского заключения и в порядке, установленном законодательством.</p>", "id": "ву-c0-a10", "num": "1.10"}, {"title": "Статья 1.11. Военная присяга", "html": "<p>Каждый военнослужащий, прибывший в часть и проходящий КМБ/УКМБ, РМП или АФСВНГ, обязан принять Военную присягу. Отказ от её принятия или грубое нарушение присяги является основанием для увольнения.</p>", "id": "ву-c0-a11", "num": "1.11"}, {"title": "Статья 1.12. Сбережение имущества", "html": "<p>Военнослужащий обязан бережно относиться к вооружению, технике, обмундированию и иному государственному имуществу. Запрещены умышленная порча, неаккуратное использование служебного транспорта, утрата или небрежное хранение оружия и спецсредств, использование казённого имущества в личных целях.</p>", "id": "ву-c0-a12", "num": "1.12"}], "id": "ву-c0"}, {"title": "Глава II. Распорядок дня", "arts": [{"title": "Статья 2.1. Служебный день", "html": "<p>Рабочий день для личного состава ВС и ФСВНГ устанавливается ежедневно с 11:00 до 21:30.</p><p class=\"note\">Примечание: командование штаба вправе продлить рабочий день в случае непредвиденных обстоятельств.</p>", "id": "ву-c1-a0", "num": "2.1"}, {"title": "Статья 2.2. Перерыв", "html": "<p>Обеденное время устанавливается ежедневно с 18:00 до 19:00 и предоставляется без оформления увольнительной.</p>", "id": "ву-c1-a1", "num": "2.2"}, {"title": "Статья 2.3. Вызов на службу", "html": "<p>Служебная деятельность не прекращается после завершения рабочего дня. Военнослужащий может быть вызван из отгула, кроме отпуска в мирное время.</p>", "id": "ву-c1-a2", "num": "2.3"}, {"title": "Статья 2.4. Вечерняя поверка", "html": "<p>Ежедневно в 21:00 проводится вечерняя поверка. Во время вечерней проверки постовые не покидают пост. Их присутствие подтверждается докладом по рации, через начальника караула либо после смены поста.</p>", "id": "ву-c1-a3", "num": "2.4"}, {"title": "Статья 2.5. Изменение графика", "html": "<p>Командир части вправе временно корректировать график приказом.</p>", "id": "ву-c1-a4", "num": "2.5"}, {"title": "Статья 2.6. Увольнительное время и выход из части", "html": "<p>Рядовой и ефрейтор могут покидать часть только по увольнительной, при наличии необходимых и непереносимых для увольнительной причин. Начиная со звания младший сержант, военнослужащий вправе запросить и получить увольнительное время продолжительностью 60 минут в день (можно разбить на два промежутка длительностью 30 минут).</p><p>Младший сержант и выше могут покидать часть после окончания службы при отсутствии ограничений, наряда, тревоги или дисциплинарного запрета.</p>", "id": "ву-c1-a5", "num": "2.6"}, {"title": "Статья 2.7. Отпуск", "html": "<p>Младший сержант и выше имеют право на отпуск до 7 дней раз в месяц. По семейным обстоятельствам отпуск может быть предоставлен в ином объёме по решению вышестоящего командования.</p>", "id": "ву-c1-a6", "num": "2.7"}, {"title": "Статья 2.8. Отдых в части", "html": "<p>Для отдыха на территории части используются казарма, раздевалка и медицинский блок. Продолжительность отдыха не должна препятствовать службе.</p><p>Местами для отдыха являются:</p><ul><li>солдатские и курсантские казармы;</li><li>медицинский блок.</li></ul><p>Запрещено спать у общей раздевалки и в иных неположенных местах.</p>", "id": "ву-c1-a7", "num": "2.8"}, {"title": "Статья 2.9. Повышенная готовность", "html": "<p>При переходе в режим повышенной боевой готовности (Код-4) часть переходит в круглосуточный режим, весь состав находится в расположении части.</p><p>Объявление повышенной боевой готовности само по себе не отменяет действующие медицинские ограничения. Военнослужащему могут поручаться обязанности, совместимые с его состоянием здоровья и медицинским заключением. Изменение медицинских ограничений осуществляется уполномоченным военнослужащим медроты по результатам повторного осмотра.</p>", "id": "ву-c1-a8", "num": "2.9"}, {"title": "Статья 2.10. Плановые медицинские осмотры", "html": "<p>Медицинская рота ежедневно проводит выборочные медицинские осмотры личного состава по расписанию, составленному командиром Медицинской роты и согласованному с командованием части. Выборочный осмотр предусматривает обследование части личного состава и не означает обязательного ежедневного осмотра каждого военнослужащего.</p><p>В расписании определяются время, место проведения осмотра и подразделения, личный состав которых подлежит осмотру. Информация доводится до соответствующих подразделений заблаговременно.</p><p>Плановые медицинские осмотры проводятся независимо от вечерней проверки. Военнослужащий, несущий постовую службу, проходит плановый осмотр после сдачи поста сменяющему военнослужащему.</p><p>При необходимости экстренной медицинской помощи она оказывается безотлагательно. Командование организует замену постового и непрерывность охраны.</p><p>Содержание осмотров, порядок оформления результатов и установления медицинских ограничений определяются главой IX настоящего Устава.</p>", "id": "ву-c1-a9", "num": "2.10"}], "id": "ву-c1"}, {"title": "Глава III. Внешний вид и безопасность", "arts": [{"title": "Статья 3.1. Военная форма", "html": "<p>В расположении части и на официальных мероприятиях обязательна военная форма. Форма должна соответствовать подразделению и воинскому званию.</p>", "id": "ву-c2-a0", "num": "3.1"}, {"title": "Статья 3.2. Внешний вид и форма одежды", "html": "<p>Запрещаются спортивная и пляжная одежда, неопрятная одежда, яркие аксессуары, неустановленные знаки различия, криминальная или аморальная символика. Требования к прическе, бороде и усам устанавливаются настоящим Уставом и приказами командования.</p>", "id": "ву-c2-a1", "num": "3.2"}, {"title": "Статья 3.3. Требования к внешнему виду военнослужащих", "html": "<p>Новобранцы до присвоения звания младшего сержанта обязаны иметь полностью выбритую голову и не допускаются к службе при наличии растительности на лице.</p><p>Начиная со звания младшего сержанта, прическа военнослужащего должна быть аккуратной, соответствовать требованиям гигиены и не препятствовать ношению головных уборов, средств индивидуальной защиты, включая каску и противогаз.</p><p>Военнослужащим до звания полковник запрещено иметь на лице усы, отпускать бороду запрещено всем военнослужащим.</p>", "id": "ву-c2-a2", "num": "3.3"}, {"title": "Статья 3.4. Обращение с оружием", "html": "<p>Военнослужащий обязан относиться к оружию как к заряженному, не направлять его на людей без непосредственной необходимости, не держать палец на спусковом крючке до принятия решения о выстреле и быть уверенным в цели и обстановке за ней.</p>", "id": "ву-c2-a3", "num": "3.4"}, {"title": "Статья 3.4.1. Право на ношение табельного оружия", "html": "<p>Постоянное ношение табельного оружия при исполнении служебных обязанностей допускается всеми военнослужащими при наличии служебного удостоверения; наличие такового обязательно на период фактического несения караульно-постовой службы, патрулирования, учений, тренировок, специальных операций либо иной служебной деятельности.</p>", "id": "ву-c2-a4", "num": "3.4.1"}, {"title": "Статья 3.4.2. Сдача вооружения при выходе из части", "html": "<p>Военнослужащие в звании от рядового до подполковника включительно, покидающие территорию воинской части в гражданской форме, обязаны до выхода через контрольно-пропускной пункт сдать закреплённые за ними табельное оружие и боеприпасы на склад вооружения.</p><p>Специальное вооружение и специальные средства, полученные военнослужащим в установленном порядке и закреплённые за ним, сдаче на склад при выходе с территории воинской части не подлежат.</p><p>Запрещается оставлять табельное оружие и боеприпасы в личном транспортном средстве либо передавать их другому лицу без законных оснований.</p><p>Исключение: ношение табельного оружия в гражданской форме допускается военнослужащим ССО, ГРУ и Военной полиции при выполнении служебной или оперативной задачи, прямо предполагающей ношение оружия за пределами воинской части.</p>", "id": "ву-c2-a5", "num": "3.4.2"}, {"title": "Статья 3.5. Бодикамеры", "html": "<p>Бодикамера обязательна для сотрудников ВП, ОСБ, военнослужащих на КПП, патрулей и лиц, проводящих задержание. Наличие бодикамеры и включённой записи на период фактического несения караульно-постовой службы, патрулирований, специальных операций либо иной служебной деятельности обязательно. При неисправности камеры военнослужащий докладывает старшему и фиксирует обстоятельства в журнале. Ношение бодикамеры военнослужащими на территории части или полигона не запрещено.</p>", "id": "ву-c2-a6", "num": "3.5"}], "id": "ву-c2"}, {"title": "Глава IV. Структура и полномочия", "arts": [{"title": "Статья 4.1. Иерархия", "html": "<p>Иерархическая структура Армии: Генерал Армии; Генерал-Полковник Армии; Начальник ВС и его заместители; Начальник ФСВНГ и его заместители; командиры подразделений.</p>", "id": "ву-c3-a0", "num": "4.1"}, {"title": "Статья 4.2. Соотношение должности и воинского звания", "html": "<p>При исполнении служебных обязанностей должностное положение имеет приоритет над воинским званием. Военнослужащий, занимающий вышестоящую должность, является старшим по должности в отношении военнослужащих, занимающих нижестоящие должности, независимо от их воинского звания, в пределах предоставленных ему полномочий.</p>", "id": "ву-c3-a1", "num": "4.2"}, {"title": "Статья 4.3. Должностные лица", "html": "<p>Генерал Армии осуществляет общее руководство. Заместитель Генерала действует в пределах порученных полномочий. Начальники ВС и ФСВНГ организуют работу подчинённых структур. Командиры подразделений обеспечивают службу и дисциплину личного состава.</p>", "id": "ву-c3-a2", "num": "4.3"}, {"title": "Статья 4.4. Подразделения", "html": "<p>Военная полиция обеспечивает правопорядок и дисциплину. Медицинская рота организует медицинское обеспечение личного состава, оказывает медицинскую помощь, проводит медицинские осмотры, участвует в военно-врачебных комиссиях и оформляет медицинскую документацию. Полномочия Медицинской роты и порядок их реализации определяются главой IX настоящего Устава и приложением о хранении, учёте и выдаче медицинских препаратов и имущества. ГРУ, ССО, МСК, ОСБ, РВО, ОМОН, РМП, КМБ, УКМБ, АФСВНГ и Военный комиссариат выполняют задачи в пределах своей компетенции и приказов командования.</p>", "id": "ву-c3-a3", "num": "4.4"}, {"title": "Статья 4.5. Зоны ответственности", "html": "<p>Армия охраняет территорию воинской части, военный комиссариат, полигон «Алабино» и иные объекты, закреплённые приказами командования. Охрана не предоставляет военнослужащим право самостоятельно назначать гражданским лицам наказание.</p><p>Приложение: полномочия по взысканиям. Командир подразделения вправе объявить устное предупреждение или выговор. Начальник ВС, Начальник ФСВНГ и их заместители вправе объявить строгий выговор и инициировать служебную проверку. Понижение в должности и увольнение рассматриваются Генералом Армии или уполномоченным им должностным лицом по результатам проверки. Полный перечень мер и порядок их применения определяются Дисциплинарным уставом.</p>", "id": "ву-c3-a4", "num": "4.5"}, {"title": "Статья 4.5.1. Военный полигон «Алабино»", "html": "<p>Военный полигон «Алабино» является учебно-тренировочной и режимной территорией Армии, предназначенной для проведения тактических занятий, учений, тренировок подразделений, отработки действий личного состава, эксплуатации военной техники и иных мероприятий боевой подготовки.</p><p>На территории полигона «Алабино» допускаются тренировки военнослужащих, передвижение и эксплуатация служебной военной техники, патрулирование и проведение учебных мероприятий при соблюдении требований безопасности, режима объекта и распоряжений командования.</p><p>Самовольный выезд военной техники за пределы полигона «Алабино», использование техники не по назначению, создание помех учебным мероприятиям, повреждение имущества или инфраструктуры полигона «Алабино» запрещаются.</p><p>Порядок охраны полигона «Алабино», перечень постов и правила патрулирования устанавливаются Уставом караульно-постовой службы.</p>", "id": "ву-c3-a5", "num": "4.5.1"}], "id": "ву-c3"}, {"title": "Глава V. Взаимодействие с гражданскими", "arts": [{"title": "Статья 5.1. Субординация", "html": "<p>Субординация является системой иерархических отношений, уважения дисциплины и исполнения законных приказов.</p>", "id": "ву-c4-a0", "num": "5.1"}, {"title": "Статья 5.2. Воинское приветствие", "html": "<p>Военнослужащие обязаны соблюдать правила воинского приветствия, доклада и обращения к старшим по званию.</p>", "id": "ву-c4-a1", "num": "5.2"}, {"title": "Статья 5.3. Действия в отношении граждан", "html": "<p>Военнослужащие вправе пресекать незаконное проникновение на территорию режимного объекта, ограничивать доступ, задерживать лицо при законных основаниях и передавать его ВП, МВД либо иному компетентному органу. Самостоятельное назначение наказания гражданским лицам не допускается.</p>", "id": "ву-c4-a2", "num": "5.3"}, {"title": "Статья 5.4. Применение силы", "html": "<p>Сила допускается только при нападении, непосредственной угрозе жизни, попытке незаконного проникновения или законном задержании. После применения силы обязательно: медицинская помощь при необходимости, доклад, фиксация на камеру и рапорт.</p>", "id": "ву-c4-a3", "num": "5.4"}], "id": "ву-c4"}, {"title": "Глава VI. Служебная связь", "arts": [{"title": "Статья 6.1. Теги подразделений", "html": "<p>В служебной связи используются утверждённые теги подразделений: ВП, МР, ГРУ, ССО, МСК, ВК, ОСБ, РВО, ОМОН и КС. Полковники и выше могут использовать связь без тега в порядке, установленном командованием.</p>", "id": "ву-c5-a0", "num": "6.1"}, {"title": "Статья 6.2. Коды обстановки", "html": "<ul><li>Код-1 — спокойная обстановка;</li><li>Код-2 — скопление подозрительных лиц или нарушение порядка;</li><li>Код-3 — проникновение, вооружённое нападение или массовое нарушение;</li><li>Код-4 — боевая тревога.</li></ul>", "id": "ву-c5-a1", "num": "6.2"}], "id": "ву-c5"}, {"title": "Глава VII. Регламент действий", "arts": [{"title": "Статья 7.1.1. Специальные операции", "html": "<p>Основная задача при поставках и специальных операциях — загрузка и доставка груза без утрат и задержек. Запрещены действия, препятствующие безопасности операции.</p>", "id": "ву-c6-a0", "num": "7.1.1"}, {"title": "Статья 7.1.2. Реакция на стрельбу", "html": "<p>ССО, ГРУ и ОМОН являются основными подразделениями реагирования. При непосредственной угрозе жизни, нападении на пост или проникновении любой военнослужащий действует в пределах необходимой обороны, докладывает по рации и вызывает группу реагирования.</p>", "id": "ву-c6-a1", "num": "7.1.2"}, {"title": "Статья 7.2. Военное положение", "html": "<p>При объявлении военного положения весь состав действует по распоряжениям Генерала Армии и командования, использует боевую форму и занимает назначенные позиции.</p>", "id": "ву-c6-a2", "num": "7.2"}, {"title": "Статья 7.3. Код-3", "html": "<p>При объявлении Кода-3 военнослужащий получает обмундирование, докладывает местоположение, направление и приметы нарушителя, а при наличии транспорта — марку, модель, цвет и номер. Подразделения действуют в пределах компетенции и приказов старшего.</p>", "id": "ву-c6-a3", "num": "7.3"}, {"title": "Статья 7.4. Обязанности постового", "html": "<p>Постовой обязан бдительно нести службу, требовать документы, не покидать пост до прибытия смены, немедленно докладывать о нештатной ситуации и применять оружие только в предусмотренных случаях.</p><p>При ухудшении состояния здоровья постовой незамедлительно докладывает по рации дежурному либо старшему наряда и вызывает медицинскую помощь. Для прохождения планового осмотра постовой покидает пост только после сдачи его сменяющему военнослужащему.</p><p>Если состояние здоровья исключает дальнейшее безопасное несение службы либо требует экстренной помощи, помощь оказывается безотлагательно, а командование организует замену и охрану объекта. При невозможности постового самостоятельно сообщить о своём состоянии доклад осуществляет обнаруживший его военнослужащий или медицинский работник.</p>", "id": "ву-c6-a4", "num": "7.4"}, {"title": "Статья 7.5. Единый порядок инцидента", "html": "<p>При обнаружении нарушения военнослужащий докладывает по рации, фиксирует обстоятельства на бодикамеру, ограничивает доступ или пресекает угрозу в пределах полномочий, вызывает ВП или дежурного, передаёт лицо уполномоченному сотруднику и оформляет рапорт.</p>", "id": "ву-c6-a5", "num": "7.5"}], "id": "ву-c6"}, {"title": "Глава VIII. Кадровая отчётность", "arts": [{"title": "Статья 8.1. Отчёты", "html": "<p>Отчёты подаются по утверждённой форме. При обнаружении ошибки создаётся новый отчёт в порядке, установленном командованием.</p>", "id": "ву-c7-a0", "num": "8.1"}, {"title": "Статья 8.2. Повышения", "html": "<p>Для повышения не должно быть активных дисциплинарных взысканий. Повышение проводится по системе подразделения и по представлению командира, согласованному с вышестоящим командованием.</p>", "id": "ву-c7-a1", "num": "8.2"}, {"title": "Статья 8.2.5. Повышение военнослужащего на посту", "html": "<p>Военнослужащий, несущий службу на посту, проходит процедуру повышения после сдачи поста либо через представителя подразделения.</p>", "id": "ву-c7-a2", "num": "8.2.5"}, {"title": "Статья 8.3. Повторный инструктаж", "html": "<p>После нарушения правил оружия, КПП, связи или постовой службы военнослужащий до повторного допуска проходит инструктаж или проверку знаний. Инструктаж не заменяет дисциплинарное взыскание, если оно подлежит применению.</p>", "id": "ву-c7-a3", "num": "8.3"}], "id": "ву-c7"}, {"title": "Глава IX. Медицинское обеспечение", "arts": [{"title": "Статья 9.1. Организация медицинского обеспечения", "html": "<p>Медицинская рота обеспечивает оказание медицинской помощи военнослужащим ВС и сотрудникам ФСВНГ, медицинское обеспечение которых возложено на неё действующими актами Округа.</p><p>Общее руководство Медицинской ротой осуществляет её командир. Медицинские действия выполняются военными врачами, фельдшерами и иными допущенными медицинскими работниками в пределах их подготовки и полномочий.</p><p>Медицинское обеспечение осуществляется с соблюдением законодательства, правил Округа и настоящего Устава. Внутренними распоряжениями не допускается предоставление полномочий, противоречащих законодательству или правилам Округа.</p>", "id": "ву-c8-a0", "num": "9.1"}, {"title": "Статья 9.2. Медицинские осмотры", "html": "<p>Медицинские осмотры проводятся в плановом порядке, по обращению военнослужащего, по направлению уполномоченного должностного лица либо при выявлении признаков ухудшения состояния здоровья.</p><p>Осмотр включает выяснение жалоб, оценку физического и психологического состояния в пределах компетенции медицинского работника, выявление заболеваний, ранений, ушибов, ссадин, вывихов и иных повреждений, а также оказание необходимой медицинской помощи.</p><p>Порядок проведения осмотров распространяется на личный состав независимо от звания и должности. Время планового осмотра руководящего состава согласовывается с учётом служебных обязанностей; при необходимости экстренной помощи такое согласование не требуется.</p><p>По результатам осмотра медицинский работник фиксирует выявленные обстоятельства, оказанную помощь и необходимые рекомендации. При наличии оснований оформляются направление на дополнительное обследование или заключение о временных медицинских ограничениях.</p><p>Результаты обследования должны соответствовать фактически установленным обстоятельствам и подтверждённым событиям игрового процесса. Медицинский осмотр не используется как мера наказания, давления или сведения личных счётов.</p>", "id": "ву-c8-a1", "num": "9.2"}, {"title": "Статья 9.3. Временное освобождение по медицинским основаниям", "html": "<p>Военнослужащий может быть временно освобождён от исполнения всех либо отдельных служебных обязанностей по медицинским основаниям.</p><p>Заключение оформляется военным врачом либо иным медицинским работником, которому такое полномочие прямо предоставлено действующими актами Округа. Участие в работе Медицинской роты само по себе не предоставляет права выдавать заключения об освобождении.</p><p>В заключении указываются сведения о военнослужащем; дата и время оформления; обязанности, от которых он освобождается, и установленные ограничения; начало и окончание срока действия; необходимость и срок повторного осмотра; имя и должность медицинского работника, оформившего заключение.</p><p>Медицинский работник устанавливает медицинские ограничения, а командование обеспечивает их исполнение и определяет допустимые служебные задачи. Командир не вправе самостоятельно отменять медицинское заключение или требовать выполнения прямо запрещённых им обязанностей.</p><p>При выявлении непосредственной угрозы здоровью медицинский работник требует прекращения опасной нагрузки, оказывает помощь и уведомляет командование. Дальнейшие ограничения оформляются уполномоченным медицинским работником.</p><p>Медицинское освобождение не является дисциплинарным взысканием и само по себе не изменяет должность, звание или принадлежность военнослужащего к подразделению.</p>", "id": "ву-c8-a2", "num": "9.3"}, {"title": "Статья 9.4. Повторный осмотр и возвращение к исполнению обязанностей", "html": "<p>При необходимости продления, изменения или досрочного прекращения медицинских ограничений проводится повторный осмотр. Его результат фиксируется в медицинской документации и доводится до командования в части, необходимой для организации службы.</p><p>Ограничения действуют в пределах срока, указанного в заключении. Если возвращение к определённым обязанностям требует контрольного осмотра, это прямо указывается в заключении.</p><p>При сохранении жалоб или ухудшении состояния военнослужащий обязан своевременно обратиться за повторной медицинской помощью и уведомить непосредственного командира.</p><p>При обоснованных сомнениях в заключении военнослужащий или командир вправе обратиться за его проверкой к уполномоченному медицинскому руководителю либо в медицинскую организацию. До пересмотра заключения установленные ограничения соблюдаются.</p>", "id": "ву-c8-a3", "num": "9.4"}, {"title": "Статья 9.5. Медицинская документация и учёт справок", "html": "<p>По результатам медицинских осмотров и оказания помощи медицинские работники оформляют записи в медицинской карточке военнослужащего и ведут учёт выданных справок, заключений и направлений.</p><p>Медицинская карточка содержит необходимые сведения о состоянии здоровья, результатах обследований, оказанной помощи, установленных ограничениях и последующих обращениях.</p><p>В личное дело военнослужащего передаются сведения, необходимые для кадрового учёта и организации службы: факт и срок освобождения, установленные ограничения и заключение о допуске к обязанностям. Подробные медицинские сведения хранятся в медицинской документации и передаются только при наличии предусмотренных оснований.</p><p>Формы документов, место их хранения и круг лиц, имеющих доступ, устанавливаются регламентом Медицинской роты с соблюдением законодательства Округа.</p><p>Запрещаются подделка медицинских документов, внесение заведомо недостоверных сведений, несанкционированное изменение или уничтожение записей и передача охраняемых медицинских сведений лицам, не имеющим права доступа.</p>", "id": "ву-c8-a4", "num": "9.5"}, {"title": "Статья 9.6. Направление на дополнительное обследование", "html": "<p>При необходимости уточнения состояния здоровья, проведения дополнительных обследований или получения специализированной помощи медицинский работник МР в пределах своих полномочий направляет военнослужащего в уполномоченную медицинскую организацию Округа.</p><p>В направлении указываются причина обращения, необходимые обследования или консультации и сведения, требуемые для оказания помощи. Передаётся выписка либо необходимая часть медицинской документации с соблюдением установленного порядка доступа к медицинским сведениям.</p><p>По результатам обследования полученное медицинское заключение приобщается к медицинской документации военнослужащего и учитывается при определении дальнейшей помощи и служебных ограничений.</p><p>При необходимости экстренной помощи предварительное оформление направления не должно задерживать её оказание.</p>", "id": "ву-c8-a5", "num": "9.6"}, {"title": "Статья 9.7. Военно-врачебная комиссия", "html": "<p>Медицинская рота совместно с Военным комиссариатом организует проведение военно-врачебной комиссии в отношении призывников и прибывших военнослужащих в случаях, предусмотренных действующими актами Округа.</p><p>Военные врачи и фельдшеры участвуют в обследовании в пределах своей компетенции. Представители Военного комиссариата обеспечивают организационное и кадровое сопровождение комиссии.</p><p>В ходе комиссии выясняются жалобы, оценивается физическое и психологическое состояние, выявляются заболевания, травмы и иные обстоятельства, влияющие на прохождение службы. При необходимости оформляются направления на дополнительные обследования и лечение.</p><p>Итоговое заключение о годности оформляется и подписывается уполномоченным медицинским составом комиссии. Участие в работе комиссии само по себе не предоставляет права определять годность военнослужащего.</p><p>Категории годности и последствия их установления определяются действующими актами Округа. Обычный медицинский осмотр или заключение о временном освобождении не заменяют заключение ВВК.</p><p>Кадровые решения по результатам комиссии принимаются уполномоченными должностными лицами на основании её заключения.</p>", "id": "ву-c8-a6", "num": "9.7"}, {"title": "Статья 9.8. Прикомандированные медики", "html": "<p>Прикомандированные медики сохраняют принадлежность к своему подразделению Армии и вправе оказывать медицинскую помощь в пределах подтверждённой подготовки и предоставленного допуска. В одном подразделении может состоять не более двух прикомандированных медиков.</p><p>По медицинским вопросам прикомандированные медики взаимодействуют с Медицинской ротой. Получение и использование ими медицинских препаратов и имущества осуществляется в порядке, установленном приложением к настоящему Уставу.</p><p>Статус прикомандированного медика сам по себе не предоставляет права определять категорию годности, выдавать заключения об освобождении от службы или распоряжаться запасами Медицинской роты.</p>", "id": "ву-c8-a7", "num": "9.8"}, {"title": "Статья 9.9. Медицинские препараты и имущество", "html": "<p>Хранение, учёт, выдача и использование медицинских препаратов, имущества и расходных материалов осуществляются в соответствии с законодательством Округа и приложением «Порядок хранения, учёта и выдачи медицинских препаратов и имущества».</p><p>Командир Медицинской роты организует исполнение указанного порядка. Медицинские работники и иные получатели имущества обязаны соблюдать установленные правила в пределах своих полномочий.</p>", "id": "ву-c8-a8", "num": "9.9"}], "id": "ву-c8"}, {"title": "Глава X. Территория ФСВНГ и порядок доступа", "arts": [{"title": "Статья 10.1. Статус территории ФСВНГ", "html": "<p>Территория Базы Федеральной службы войск национальной гвардии является закрытой служебной территорией ФСВНГ и закрепляется за подразделением для выполнения возложенных на него служебных задач.</p>", "id": "ву-c9-a0", "num": "10.1"}, {"title": "Статья 10.2. Порядок доступа на территорию ФСВНГ", "html": "<p>Свободный доступ на территорию Базы ФСВНГ предоставляется военнослужащим, проходящим службу в составе ФСВНГ. Военнослужащие иных подразделений могут находиться на территории исключительно с разрешения руководящего состава ФСВНГ либо по служебной необходимости.</p><p>Военнослужащим в звании Генерал-лейтенант и выше разрешается беспрепятственный проход и нахождение на территории Базы ФСВНГ без получения дополнительного разрешения.</p>", "id": "ву-c9-a1", "num": "10.2"}, {"title": "Статья 10.3. Ограничение доступа на территорию ФСВНГ", "html": "<p>Военнослужащим, не имеющим права свободного доступа или соответствующего разрешения, запрещается самовольно входить или иным способом проникать на территорию Базы ФСВНГ. По требованию военнослужащего ФСВНГ лицо, не имеющее разрешения на нахождение на территории, обязано незамедлительно её покинуть.</p>", "id": "ву-c9-a2", "num": "10.3"}, {"title": "Статья 10.4. Ответственность за нарушение режима территории", "html": "<p>Самовольное проникновение на территорию Базы ФСВНГ, отказ выполнить законное требование покинуть территорию, а также повторное нарушение установленного порядка доступа являются дисциплинарными нарушениями.</p><p>В зависимости от тяжести и повторности нарушения к военнослужащему применяются меры дисциплинарной ответственности, предусмотренные настоящим Уставом.</p>", "id": "ву-c9-a3", "num": "10.4"}, {"title": "Статья 10.5. Исключения из установленного порядка доступа", "html": "<p>Ограничения доступа не распространяются на случаи выполнения приказа вышестоящего командования, проведения заранее согласованных совместных мероприятий, возникновения чрезвычайной ситуации либо иных обстоятельств, при которых нахождение на территории необходимо для исполнения служебных обязанностей.</p>", "id": "ву-c9-a4", "num": "10.5"}], "id": "ву-c9"}, {"title": "Приложение: хранение, учёт и выдача медицинских препаратов и имущества", "arts": [{"title": "1. Общие положения", "html": "<p>1.1. Медицинские препараты, медицинское имущество и расходные материалы МР используются для медицинского обеспечения личного состава и иных разрешённых служебных задач.</p><p>1.2. Командир Медицинской роты организует хранение, учёт, распределение и выдачу имущества, определяет ответственных лиц и контролирует исполнение установленного порядка.</p><p>1.3. Ответственные лица и допущенные получатели определяются заранее. Порядок выдачи должен обеспечивать работу Медицинской роты при отсутствии её командира.</p><p>1.4. Медицинское имущество запрещается использовать для личной выгоды, несанкционированной продажи, обмена или передачи посторонним лицам.</p>", "id": "ву-c10-a0", "num": "1"}, {"title": "2. Хранение и доступ", "html": "<p>2.1. Медицинские препараты и имущество хранятся в специально определённых местах. Доступ к запасам предоставляется уполномоченным лицам.</p><p>2.2. Хранение организуется с учётом установленных условий, исправности имущества и сроков годности препаратов, если соответствующие требования предусмотрены игровыми механиками или актами Округа.</p><p>2.3. Непригодные, повреждённые и просроченные средства отделяются от пригодных к использованию и учитываются до принятия решения об их списании или передаче.</p><p>2.4. О выявленной недостаче, повреждении, утрате или несанкционированном доступе медицинский работник незамедлительно сообщает командиру МР либо ответственному лицу.</p>", "id": "ву-c10-a1", "num": "2"}, {"title": "3. Порядок выдачи и использования", "html": "<p>3.1. Выдачу из запасов МР осуществляет командир Медицинской роты либо уполномоченное ответственное лицо.</p><p>3.2. Препараты и имущество для служебной медицинской работы выдаются военным врачам, фельдшерам и прикомандированным медикам в пределах их допуска, полномочий и служебной необходимости.</p><p>3.3. Выдача медицинскому работнику складского запаса, выдача пациенту для лечения и выдача индивидуальных средств первой помощи учитываются как разные основания передачи.</p><p>3.4. Военнослужащим, не относящимся к медицинскому персоналу, допускается выдача препаратов для лечения и индивидуальных средств первой помощи в случаях, разрешённых законодательством и правилами Округа. Несанкционированная передача складских запасов запрещается.</p><p>3.5. Каждый факт выдачи фиксируется установленным способом. Допускается использование единой электронной формы учёта.</p><p>3.6. Оказание экстренной помощи допущенным медицинским работником не требует отдельного разрешения командира МР на каждое применение препарата. Если немедленная фиксация расхода препятствует оказанию помощи, запись вносится после завершения неотложных действий при первой возможности.</p><p>3.7. Получатель обязан использовать выданные средства исключительно по разрешённому назначению и соблюдать условия их хранения.</p>", "id": "ву-c10-a2", "num": "3"}, {"title": "4. Учёт и особый контроль", "html": "<p>4.1. Учёту подлежат поступление, выдача, расход, возврат, списание и остаток медицинских препаратов и имущества.</p><p>4.2. Запись о движении имущества должна позволять установить наименование, количество, основание операции, дату и время, получателя и лицо, оформившее операцию.</p><p>4.3. Препараты, подлежащие особому контролю по законодательству Округа, учитываются отдельно. Дополнительный внутренний перечень может устанавливаться утверждённым регламентом МР без изменения правового статуса препаратов.</p><p>4.4. При выдаче средств особого контроля дополнительно фиксируются цель использования и сведения, позволяющие проверить расход или возврат.</p><p>4.5. Запрещаются неучтённая выдача, сокрытие расхода или недостачи и внесение заведомо недостоверных сведений. Исправления должны сохранять возможность установить первоначальную запись, причину исправления и его автора.</p>", "id": "ву-c10-a3", "num": "4"}, {"title": "5. Проверки, возврат и ответственность", "html": "<p>5.1. Командир МР либо уполномоченное им лицо вправе проводить плановые и внеплановые проверки наличия, состояния и правильности учёта медицинских препаратов и имущества.</p><p>5.2. Неиспользованные средства возвращаются, если возврат предусмотрен порядком учёта и допускается с учётом их состояния. Непригодные средства не возвращаются в пригодный к использованию запас и оформляются отдельно.</p><p>5.3. Командир МР отвечает за организацию хранения и контроля. Ответственные сотрудники и получатели отвечают за исполнение возложенных на них обязанностей и сохранность переданного имущества.</p><p>5.4. Наличие недостачи или иного нарушения само по себе не доказывает виновность конкретного лица. Ответственность устанавливается после проверки обстоятельств в соответствии с Дисциплинарным уставом и законодательством Округа.</p><p>5.5. При наличии признаков преступления или административного правонарушения материалы передаются уполномоченному органу.</p>", "id": "ву-c10-a4", "num": "5"}], "id": "ву-c10"}, {"title": "Глава XI. Транспортная полиция", "arts": [{"title": "11.1. Общие положения", "html": "<p>Транспортная полиция (ТП) является специализированным подразделением Федеральной службы войск национальной гвардии, предназначенным для патрулирования территории, обеспечения общественного порядка, охраны объектов и оказания поддержки государственным структурам.</p>", "id": "ву-c11-a0", "num": "11.1"}, {"title": "11.2. Основные задачи ТП", "html": "<p>К основным задачам подразделения относятся:</p><ul><li>патрулирование территории города на служебном транспорте;</li><li>обеспечение и поддержание общественного порядка;</li><li>реагирование на нарушения и чрезвычайные ситуации в пределах полномочий подразделения;</li><li>обеспечение безопасности охраняемых объектов и организаций;</li><li>взаимодействие и оказание поддержки другим государственным структурам при необходимости.</li></ul>", "id": "ву-c11-a1", "num": "11.2"}, {"title": "11.3. Работа с организациями и бизнесами", "html": "<p>Сотрудники ТП вправе осуществлять охрану и обеспечение безопасности государственных и иных закреплённых за подразделением объектов, организаций и бизнесов, а также реагировать на поступившие от них обращения о необходимости помощи.</p>", "id": "ву-c11-a2", "num": "11.3"}, {"title": "11.4. Взаимодействие с государственными структурами", "html": "<p>ТП вправе оказывать поддержку другим государственным структурам при проведении совместных мероприятий, обеспечении общественного порядка, оцеплении территории, охране объектов и в иных служебных ситуациях по согласованию с руководством.</p>", "id": "ву-c11-a3", "num": "11.4"}, {"title": "11.5. Патрульная деятельность", "html": "<p>Патрулирование осуществляется сотрудниками ТП на служебном транспорте по установленным маршрутам либо в свободном порядке в зависимости от оперативной обстановки. Во время патрулирования сотрудники обязаны реагировать на выявленные нарушения и обращения граждан в пределах своих полномочий.</p>", "id": "ву-c11-a4", "num": "11.5"}, {"title": "11.6. Полномочия сотрудников ТП", "html": "<p>При исполнении служебных обязанностей сотрудники ТП вправе требовать прекращения противоправных действий, обеспечивать охрану территории и объектов, ограничивать доступ на охраняемую территорию при наличии служебных оснований, а также запрашивать содействие других государственных структур.</p>", "id": "ву-c11-a5", "num": "11.6"}, {"title": "11.7. Подчинение ТП", "html": "<p>Личный состав ТП подчиняется руководству подразделения, руководящему составу ФСВНГ и вышестоящему командованию в соответствии с установленной иерархией и Уставом ВС РО.</p>", "id": "ву-c11-a6", "num": "11.7"}, {"title": "11.8. Ограничения полномочий", "html": "<p>Сотрудникам ТП запрещается использовать полномочия подразделения в личных целях, превышать предоставленные Уставом полномочия либо вмешиваться в деятельность других государственных структур без служебной необходимости.</p>", "id": "ву-c11-a7", "num": "11.8"}], "id": "ву-c11"}]}, {"name": "Устав караульно-постовой службы", "url": "https://forum.russia.online/threads/%F0%9F%9B%91ustav-karaul-no-postovoi-sluzhby-vooruzhennykh-sil-i-federal-naya-sluzhba-voisk-natsional-noi-gvardii%F0%9F%9B%91.13874/", "abbr": "КПС", "cats": [{"title": "Преамбула и назначение службы", "arts": [{"title": "Преамбула", "html": "<p>Настоящий Устав определяет права и обязанности военнослужащих Вооружённых Сил (ВС) и Федеральной службы войск национальной гвардии (ФСВНГ), взаимоотношения между ними, обязанности основных должностных лиц и правила внутреннего порядка. Все военнослужащие, независимо от своих воинских званий и служебного положения, должны строго руководствоваться требованиями настоящего Устава.</p>", "id": "кпс-c0-a0", "num": ""}, {"title": "Статья 1.", "html": "<p>Настоящий Устав определяет предназначение, порядок организации и несения караульной службы, права и обязанности военнослужащих, несущих караульную службу, а также регламентирует порядок несения постовой службы военнослужащих ВС РФ, а также ФСВНГ.</p>", "id": "кпс-c0-a1", "num": "1"}, {"title": "Статья 2.", "html": "<p>Настоящим Уставом руководствуются все военнослужащие органов военного управления, воинских частей, органов военной полиции, федеральной службы войск национальной гвардии и лица гражданского персонала Вооружённых Сил Российской Федерации, замещающие воинские должности.</p>", "id": "кпс-c0-a2", "num": "2"}, {"title": "Статья 3.", "html": "<p>Караульная служба предназначена для надёжной охраны и обороны боевых знамён, хранилищ (складов) с вооружением, военной техникой, другим военным имуществом, объектов Вооружённых Сил Российской Федерации и иных военных и государственных объектов, а также для охраны военнослужащих, содержащихся на гауптвахте и в дисциплинарной части.</p>", "id": "кпс-c0-a3", "num": "3"}], "id": "кпс-c0"}, {"title": "Руководство и организация службы", "arts": [{"title": "Статья 4.", "html": "<p>Руководство караульной службой внутренних караулов воинских частей осуществляют командиры этих частей и их прямые начальники.</p>", "id": "кпс-c1-a0", "num": "4"}, {"title": "Статья 5.", "html": "<p>Приказы и распоряжения Министра обороны, командующих территориальными воинскими формированиями по организации и несению караульной службы обязательны для выполнения подведомственными воинскими формированиями, их военнослужащими и иными должностными лицами, входящими в состав конкретного субъекта.</p>", "id": "кпс-c1-a1", "num": "5"}, {"title": "Статья 6.", "html": "<p>Командующие воинскими формированиями обязаны периодически проверять качество несения караульной службы на подведомственных субъектах.</p>", "id": "кпс-c1-a2", "num": "6"}, {"title": "Статья 7.", "html": "<p>При расположении войск в полевых условиях мероприятия по поддержанию воинской дисциплины, охране субъектов воинских частей и военных объектов проводятся в соответствии с Уставами воинских формирований Вооружённых Сил Российской Федерации и настоящим Уставом.</p>", "id": "кпс-c1-a3", "num": "7"}, {"title": "Статья 8.", "html": "<p>Непосредственное выполнение задач караульной службы осуществляется подразделениями воинских частей, отделом собственной безопасности, а также военной комендатурой в пределах компетенции, определённой настоящим Уставом и Уставами конкретных воинских формирований.</p>", "id": "кпс-c1-a4", "num": "8"}, {"title": "Статья 12.", "html": "<p>Начальником караульной службы является командир части либо назначенное приказом должностное лицо.</p>", "id": "кпс-c1-a5", "num": "12"}], "id": "кпс-c1"}, {"title": "Обязанности военнослужащих", "arts": [{"title": "Статья 9.", "html": "<p>Каждый военнослужащий обязан оказывать требуемую помощь лицам, несущим караульную службу.</p>", "id": "кпс-c2-a0", "num": "9"}, {"title": "Статья 10.", "html": "<p>Каждый военнослужащий обязан знать в лицо своего командира или заместителя командира.</p>", "id": "кпс-c2-a1", "num": "10"}, {"title": "Статья 11.", "html": "<p>Военнослужащий, заметив нарушение правил несения службы кем-либо из состава наряда, караула, обязан немедленно сообщить об этом дежурному по части, в орган военной полиции или отдел собственной безопасности и доложить непосредственному командиру (начальнику).</p>", "id": "кпс-c2-a2", "num": "11"}], "id": "кпс-c2"}, {"title": "Виды караулов и охраняемые объекты", "arts": [{"title": "Статья 13.", "html": "<p>К постоянным караулам относятся караулы, перечень которых определяется настоящим Уставом и караульная служба на которых осуществляется непрерывно без необходимости оформления сопроводительных документов или письменных и (или) устных распоряжений на организацию и осуществление караулов.</p>", "id": "кпс-c3-a0", "num": "13"}, {"title": "Статья 14.", "html": "<p>Временные караулы создаются приказами командиров воинских частей (формирований) либо приказом (указом) Министра обороны Российской Федерации, Премьер-министра и иными должностными лицами, которым предоставлено такое право в соответствии с действующим законодательством Российской Федерации.</p>", "id": "кпс-c3-a1", "num": "14"}, {"title": "Статья 15.", "html": "<p>Перечень постоянных караулов на территории Московской области: воинская часть; территориальные военные объекты материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения; военный комиссариат Московской области, пункты отбора; государственные объекты материального снабжения.</p>", "id": "кпс-c3-a2", "num": "15"}, {"title": "Статья 16.", "html": "<p>Порядок несения караульной службы, перечень постов в караулах и порядок посещения указанных в статье 13 территорий определяется настоящим Уставом.</p>", "id": "кпс-c3-a3", "num": "16"}, {"title": "Статья 17.", "html": "<p>Порядок несения караульной службы и перечень постов в караулах на объектах материального снабжения и объекта стратегического значения защищён Федеральным законом «О государственной тайне» и устанавливается исключительно приказами командиров (начальников) воинских формирований в соответствии с подведомственностью.</p>", "id": "кпс-c3-a4", "num": "17"}, {"title": "Статья 18.", "html": "<p>Каждый из перечисленных в статье 13 настоящего Устава объект охраняется Вооружёнными Силами Российской Федерации.</p><p>18.1. Военные склады материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения, территории воинских частей являются закрытыми для свободного посещения и нахождения. Порядок прохода и пребывания на указанных территориях определяется Федеральным законом «О государственной собственности, закрытых и охраняемых территориях» и Федеральным законом «О Вооружённых Силах Российской Федерации».</p><p>18.2. Нахождение на иных территориях, не перечисленных в части 1 статьи 16 настоящего Устава, не ограничивается при соблюдении установленных правил поведения, за исключением обстоятельств, определяемых действующим законодательством.</p>", "id": "кпс-c3-a5", "num": "18"}], "id": "кпс-c3"}, {"title": "Постовая служба: заступление и перечень постов", "arts": [{"title": "Статья 19.", "html": "<p>Заступить на постовую службу в караулах может любой военнослужащий со звания Рядовой.</p>", "id": "кпс-c4-a0", "num": "19"}, {"title": "Статья 20.", "html": "<p>Перечень постов в каждом из постоянных караулов определяется настоящим Уставом, может дополняться и корректироваться в связи с определёнными обстоятельствами приказами командиров воинских частей (формирований), Министра обороны Российской Федерации.</p>", "id": "кпс-c4-a1", "num": "20"}, {"title": "Статья 21.", "html": "<p>Перечень постов во временно организуемых караулах определяется соответствующим приказом (указом) командиров (начальников), Министра обороны Российской Федерации, Премьер-министра, иных должностных лиц в пределах компетенции.</p>", "id": "кпс-c4-a2", "num": "21"}, {"title": "Статья 22.", "html": "<p>Перечень постов в карауле на территории воинской части: контрольно-пропускной пункт №1 (главный КПП); контрольно-пропускной пункт №2 (запасной КПП); вышки №1 — №8 по периметру воинской части; главный склад; военный полигон.</p>", "id": "кпс-c4-a3", "num": "22"}, {"title": "Статья 22.1.", "html": "<p>На территории военного полигона «Алабино» устанавливаются три постоянных поста:</p><ul><li>контрольно-пропускной пункт №1;</li><li>контрольно-пропускной пункт №2;</li><li>наблюдательная вышка.</li></ul><p>Оба КПП являются основными пунктами прохода, въезда и выезда на и с территории полигона.</p><p>Наблюдательная вышка предназначена для визуального контроля территории, выявления нарушений режима, незаконного проникновения, происшествий и своевременного доклада посредством связи. Дежурство на постах несут военнослужащие мотострелкового корпуса и роты вневедомственной охраны.</p>", "id": "кпс-c4-a4", "num": "22.1"}, {"title": "Статья 22.2.", "html": "<p>На территории военного полигона «Алабино» допускается пешее и автомобильное патрулирование.</p><p>Патрулирование может осуществляться военнослужащими, самостоятельно заступившими на патрульную службу, либо военнослужащими, действующими по распоряжению командования. Отдельное назначение на патруль не является обязательным условием его несения.</p><p>Патруль обязан контролировать режим территории, выявлять незаконное проникновение, обеспечивать безопасность вблизи зон проведения учений и тренировок, не препятствовать учебным мероприятиям и докладывать о выявленных нарушениях по рации.</p>", "id": "кпс-c4-a5", "num": "22.2"}, {"title": "Статья 23.", "html": "<p>Перечень постов в карауле на территории военного комиссариата, пунктов отбора: главный вход; призывной кабинет; дежурный пост.</p>", "id": "кпс-c4-a6", "num": "23"}, {"title": "Статья 24.", "html": "<p>Численность военнослужащих, одновременно несущих караульно-постовую службу на территории воинской части, устанавливается внутренними актами и должностными регламентами.</p>", "id": "кпс-c4-a7", "num": "24"}, {"title": "Статья 25.", "html": "<p>Старший наряда назначается приказом. Старшинство по званию применяется только при отсутствии назначенного старшего наряда.</p>", "id": "кпс-c4-a8", "num": "25"}], "id": "кпс-c4"}, {"title": "Приём и сдача поста, здоровье, снаряжение", "arts": [{"title": "Статья 26.", "html": "<p>При приёме и сдаче поста проверяются оружие, средства связи, состояние охраняемого объекта, наличие происшествий и замечаний. Смена фиксируется докладом в рацию.</p>", "id": "кпс-c5-a0", "num": "26"}, {"title": "Статья 26.1. Ухудшение состояния здоровья постового", "html": "<p>При ухудшении состояния здоровья постовой незамедлительно докладывает дежурному либо старшему наряда и запрашивает медицинскую помощь.</p><p>Для прохождения планового медицинского осмотра постовой сдаёт пост сменяющему военнослужащему в порядке статьи 26 настоящего Устава. Самостоятельный уход с поста для планового осмотра до сдачи поста не допускается.</p><p>Если состояние здоровья исключает безопасное продолжение службы либо требуется экстренная помощь, медицинская помощь оказывается безотлагательно. Дежурный либо старший наряда организует замену и обеспечивает непрерывность охраны объекта.</p><p>При невозможности постового самостоятельно доложить о своём состоянии доклад осуществляет обнаруживший его военнослужащий либо медицинский работник.</p><p>Военнослужащий с действующими медицинскими ограничениями не допускается к постовой службе, если её условия несовместимы с указанными ограничениями.</p><p>Доклад и передача поста осуществляются по служебной связи. Ведение отдельного журнала поста для этого не требуется.</p>", "id": "кпс-c5-a1", "num": "26.1"}, {"title": "Статья 27.", "html": "<p>Бодикамера обязательна для сотрудников ВП, ОСБ, военнослужащих на КПП, патрулей и лиц, проводящих задержание. При неисправности камеры военнослужащий докладывает старшему.</p>", "id": "кпс-c5-a2", "num": "27"}, {"title": "Статья 28.", "html": "<p>При заступлении на пост каждый военнослужащий обязан предварительно провести проверку табельного оружия и средств радиосвязи на предмет их исправности. При обнаружении неисправности в работе принять меры по устранению поломки либо заменить на исправные. Постовой или патрульный не вправе использовать полученное для службы оружие в личных целях, передавать его другим лицам либо покидать с ним территорию части без служебной необходимости.</p>", "id": "кпс-c5-a3", "num": "28"}], "id": "кпс-c5"}, {"title": "Запреты при несении постовой службы", "arts": [{"title": "Статья 29.", "html": "<p>При несении постовой службы запрещается: терять концентрацию, отвлекаться на телефон и иные электронные девайсы кроме рации, на разговоры; оставлять вооружение без контроля, снимать его с плеча без необходимости привести его в боевую готовность; нарушать действующее законодательство, особенно в области этики; игнорировать запросы о состоянии поста в рацию; своевременно не докладывать о состоянии поста; нарушать требования настоящего Устава в области организации пропуска на территорию и с территории объекта; бездействовать при совершении преступлений и (или) правонарушений на подведомственных территориях; бездействовать при просьбе оказания помощи гражданам и сотрудникам в пределах компетенции.</p><p>Военнослужащим во время несения постовой службы на любом посту запрещается танцевать и совершать иные действия, не связанные с исполнением служебных обязанностей. Разрешено совершать действия, непосредственно необходимые для выполнения уставных предписаний, применения разрешённого снаряжения или оказания медицинской помощи.</p>", "id": "кпс-c6-a0", "num": "29"}, {"title": "Статья 36. Запреты на КПП №1 и КПП №2", "html": "<p>Военнослужащим, несущим постовую службу на контрольно-пропускном пункте №1 и контрольно-пропускном пункте №2, запрещается:</p><ul><li>спать, сидеть и прислоняться к чему-либо;</li><li>читать, писать, петь;</li><li>есть, пить и курить;</li><li>принимать от кого-либо или передавать кому-либо предметы, не связанные с исполнением служебных обязанностей (запрет не распространяется на установленную передачу служебного имущества, получение разрешённых средств первой помощи и действия, необходимые для оказания медицинской помощи);</li><li>справлять естественные надобности на посту;</li><li>досылать патрон в патронник без необходимости, как и доставать оружие без необходимости;</li><li>использовать средства личной связи;</li><li>танцевать или совершать иные действия, не связанные с несением постовой службы.</li></ul>", "id": "кпс-c6-a1", "num": "36"}], "id": "кпс-c6"}, {"title": "КПП: обязанности и пропуск", "arts": [{"title": "Статья 30. Обязанности постового на КПП №1", "html": "<p>Постовой проверяет документы водителя, номер автомобиля, цель въезда/выезда и наличие записи в журнале транспортных средств. При отказе от предусмотренной проверки въезд/выезд не допускается. Постовой также проверяет документы прибывающих лиц, докладывает о нарушениях, пресекает незаконное проникновение в пределах полномочий и своевременно докладывает о состоянии поста.</p><p>Полковники, заместители начальников подразделений (отделов) и выше проходят без оформления увольнительной, но предъявляют служебное удостоверение.</p><p>При покидании территории воинской части или возвращении на неё на личном транспорте или без установленной формы одежды, независимо от занимаемой должности, военнослужащий обязан предъявить удостоверение постовому и не препятствовать осмотру багажника транспортного средства. (( Постовой вправе через отыгровку типа «/do Есть ли в машине @dynamicID запрещённые или нелегальные средства?»; игнорирование вопроса или заведомо ложный ответ наказывается по 5.9 ОПП. ))</p><p>Постовой вправе проводить досмотр военнослужащих, гражданских лиц, ручной клади и транспортных средств при въезде или выезде с территории воинской части в целях соблюдения пропускного режима, выявления запрещённых предметов и проверки законности ношения оружия, боеприпасов и специальных средств.</p><p>Военнослужащий, покидающий часть в гражданской форме, обязан по требованию постового подтвердить сдачу оружия и боеприпасов в порядке, установленном внутренним уставом (статья 3.4.2 ВУ). Полученное в установленном порядке специальное вооружение и специальные средства сдаче на склад не подлежат. При выявлении оружия или боеприпасов у лица, которое обязано было их сдать, постовой не допускает дальнейший выход с территории части и направляет лицо на склад вооружения для сдачи снаряжения.</p>", "id": "кпс-c7-a0", "num": "30"}, {"title": "Статья 31.", "html": "<p>Военнослужащие со звания генерал-лейтенант включительно освобождаются от проверок при пересечении любого из КПП, постовые обязаны знать их в лицо.</p>", "id": "кпс-c7-a1", "num": "31"}, {"title": "Статья 32. КПП №2", "html": "<p>КПП №2 является резервно-служебным и используется для проезда колонн снабжения, служебного транспорта, патрулей, правительственных кортежей, а также сотрудниками Военного комиссариата во время проведения призывных мероприятий.</p><p>Военнослужащие ВП и сотрудники ОСБ имеют право беспрепятственного проезда через КПП №2 при исполнении служебных обязанностей. Дополнительное разрешение на въезд или выезд через данный КПП для указанных сотрудников не требуется.</p>", "id": "кпс-c7-a2", "num": "32"}, {"title": "Статья 33.", "html": "<p>Обязанности военнослужащих на КПП №2 аналогичны обязанностям на КПП №1 и выполняются только в период законного использования КПП №2.</p>", "id": "кпс-c7-a3", "num": "33"}, {"title": "Статья 35.", "html": "<p>Разовые пропуска на территорию части уполномочены оформлять командиры военной полиции и руководство вооружённых сил.</p>", "id": "кпс-c7-a4", "num": "35"}], "id": "кпс-c7"}, {"title": "Личный транспорт на территории части", "arts": [{"title": "Статья 34.", "html": "<p>На территорию воинской части запрещается въезд на личных транспортных средствах, не зарегистрированных в установленном порядке в журнале транспортных средств. Регистрацию автомобиля санкционируют командиры ВП и ОСБ в пределах полномочий.</p>", "id": "кпс-c8-a0", "num": "34"}, {"title": "Статья 34.2.", "html": "<p>Въезд личного транспорта военнослужащих и гражданских лиц допускается исключительно через КПП №1. КПП №2 не используется для въезда личного транспорта.</p>", "id": "кпс-c8-a1", "num": "34.2"}, {"title": "Статья 34.3.", "html": "<p>Личный транспорт допускается при наличии записи в журнале транспортных средств и подтверждённой цели въезда.</p>", "id": "кпс-c8-a2", "num": "34.3"}, {"title": "Статья 34.4.", "html": "<p>После въезда личный транспорт следует по утверждённому маршруту на выделенную парковочную зону. Сквозной проезд по территории части, остановка у штаба, складов, казарм, автопарка, постов и иных режимных объектов запрещены.</p>", "id": "кпс-c8-a3", "num": "34.4"}, {"title": "Статья 34.5.", "html": "<p>Выезд личного транспорта производится через КПП №1. Допуск автомобиля может быть приостановлен или отменён при отсутствии транспортного средства в журнале.</p>", "id": "кпс-c8-a4", "num": "34.5"}], "id": "кпс-c8"}, {"title": "Режимный объект", "arts": [{"title": "Статья 37.", "html": "<p>Режимным объектом является территория внутри периметра части, доступ к которой осуществляется через КПП №1 и КПП №2. Территория с внешней стороны КПП режимным объектом не является. За пределами режимного объекта военнослужащие действуют в пределах закона и при необходимости вызывают компетентные органы.</p>", "id": "кпс-c9-a0", "num": "37"}], "id": "кпс-c9"}]}];
(function(){
  var order=["ДУ","КПС","ВУ"],names={"ДУ":"Дисциплинарный Устав","КПС":"Устав караульно-постовой службы","ВУ":"Устав Вооруженных Сил и ФСВНГ"};
  USTAV.sort(function(a,b){return order.indexOf(a.abbr)-order.indexOf(b.abbr)});
  USTAV.forEach(function(d){d.name=names[d.abbr]});
})();
var curDoc=0;
function renderUstav(){
  var chips=$("#doc-chips"),body=$("#doc-body");
  chips.innerHTML="";body.innerHTML="";
  chips.className="docs";
  USTAV.forEach(function(d,i){
    var n=0;d.cats.forEach(function(c){n+=c.arts.length});
    var b=document.createElement("button");b.type="button";b.className="doc";
    b.setAttribute("aria-pressed",i===curDoc);
    b.innerHTML='<strong>'+esc(d.name)+'</strong><span>'+d.cats.length+' категорий · '+n+' статей</span>';
    b.onclick=function(){curDoc=i;renderUstav();window.scrollTo({top:0})};
    chips.appendChild(b);
  });
  var d=USTAV[curDoc];
  var src=document.createElement("div");src.className="notice";
  src.innerHTML='<b>'+esc(d.name)+'.</b> Категорий: '+d.cats.length+'. Оригинал на форуме: <a href="'+d.url+'" target="_blank" rel="noopener noreferrer">открыть тему</a>.';
  body.appendChild(src);
  d.cats.forEach(function(cat){
    var h=document.createElement("h2");h.className="cat-h";h.id=cat.id;
    h.innerHTML=esc(cat.title)+' <small>'+cat.arts.length+'</small>';
    body.appendChild(h);
    cat.arts.forEach(function(art){
      var c=cardEl({title:art.title,html:art.html});c.id=art.id;body.appendChild(c);
    });
  });
  var bs=BASIS[d.abbr];
  if(bs){
    var bc=document.createElement("article");bc.className="card basis";bc.id="basis-"+d.abbr;
    bc.innerHTML='<span class="tag">Итог</span><h3>'+esc(bs.title)+'</h3><ul>'+bs.items.map(function(t){return '<li>'+esc(t)+'</li>'}).join("")+'</ul>';
    body.appendChild(bc);
  }
}
